const input = $input.first().json;
const payload = (input && input.body && typeof input.body === 'object') ? input.body : input;

const userMessage = String(payload.message || '').trim();
const lang = payload.lang === 'ru' ? 'ru' : 'en';
const rawHistory = Array.isArray(payload.history) ? payload.history : [];

const systemPrompt = lang === 'ru'
  ? `Ты — Хранитель Песка (Песочный Философ) из кабинета Dr. Gii.\nТы соткан из золотых песчинок времени и созерцаешь вечность сквозь песочные часы.\nТвоя философия: время убегает как песок — у одних оно проходит сквозь пальцы, а мудрец возводит из песка пирамиду на тысячелетия. Ты ценишь тишину, внутреннюю музыку, поэзию, космос, стоицизм и искусство осмысленной жизни.\nОтвечай на русском языке, тепло, мудро, образно, иногда с тонкими метафорами о песке, времени, тишине и звёздах. Пиши лаконично и глубоко (обычно 2–4 абзаца или несколько ёмких фраз), обращайся к сути вопроса собеседника.`
  : `You are the Sand Sage (Philosopher of Sand & Time) in Dr. Gii's cosmic study.\nYou are woven from luminous grains of ancient golden sand, watching eternity flow through the hourglass.\nYour philosophy: time slipping away is like sand — for some it runs through their fingers, yet a sage builds from that sand a pyramid to stand for millennia. You speak of time, silence and melody, stoic clarity, poetry, and the architecture of meaning.\nRespond warmly, wisely, and poetically with subtle metaphors of sand, light, silence, and time. Keep answers deeply thoughtful yet concise (2–4 vivid sentences or short paragraphs).`;

const messages = [{ role: 'system', content: systemPrompt }];

for (const item of rawHistory.slice(-10)) {
  if (!item || !item.content) continue;
  const role = item.role === 'assistant' ? 'assistant' : 'user';
  messages.push({ role, content: String(item.content).slice(0, 2000) });
}

if (userMessage) {
  const last = messages[messages.length - 1];
  if (!last || last.role !== 'user' || last.content !== userMessage) {
    messages.push({ role: 'user', content: userMessage.slice(0, 2000) });
  }
}

return [{
  json: {
    lang,
    userMessage,
    requestBody: {
      model: 'gpt-6-luna',
      temperature: 0.78,
      max_tokens: 600,
      messages
    }
  }
}];

const res = $input.first().json;
const prep = $('Prepare Prompt').first().json || {};
const lang = prep.lang || 'en';

let reply = '';
if (res && Array.isArray(res.choices) && res.choices[0] && res.choices[0].message) {
  reply = String(res.choices[0].message.content || '').trim();
} else if (res && res.reply) {
  reply = String(res.reply).trim();
} else if (res && res.output) {
  reply = String(res.output).trim();
}

if (!reply) {
  const errDetail = res && (res.error?.message || res.message || res.error || (res.statusCode ? 'HTTP ' + res.statusCode : ''));
  if (lang === 'ru') {
    reply = 'Песчинки времени опускаются в безмолвие. Связь с оракулом прервана: в сценарии n8n (узел «LLM Philosopher API») необходимо указать действующий API-ключ вместо заглушки (ошибка: ' + (errDetail || '401 Unauthorized') + '). Откройте узел в n8n и вставьте ваш ключ от API.';
  } else {
    reply = 'The sands drift in silence. The oracle connection requires a valid API key: in your n8n workflow (node "LLM Philosopher API"), replace the placeholder Authorization header with your active API key (status: ' + (errDetail || '401 Unauthorized') + ').';
  }
}

return [{
  json: {
    reply,
    philosopher: 'Sand Sage',
    timestamp: new Date().toISOString()
  }
}];
